func And(predicates ...predicate.DesktopMember) predicate.DesktopMember {
	return predicate.DesktopMember(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.DesktopMember) predicate.DesktopMember {
	return predicate.DesktopMember(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.DesktopMember) predicate.DesktopMember {
	return predicate.DesktopMember(sql.NotPredicates(p))
}
